/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return getDb().transaction((tx) => reserveNextIssueNumber(tx, orgId, projectId));
}

function reserveNextIssueNumber(
  tx: Parameters<Parameters<ReturnType<typeof getDb>["transaction"]>[0]>[0],
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const row = tx
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const counter = tx
    .select({ lastNumber: issueNumberCounters.lastNumber })
    .from(issueNumberCounters)
    .where(eq(issueNumberCounters.projectId, projectId))
    .get();
  const next = Math.max(row?.value ?? 0, counter?.lastNumber ?? 0) + 1;

  tx.insert(issueNumberCounters)
    .values({ projectId, orgId, lastNumber: next })
    .onConflictDoUpdate({
      target: issueNumberCounters.projectId,
      set: { orgId, lastNumber: next },
    })
    .run();

  return next;
}

/** Moves and renumbers an issue while atomically retaining both project high-water marks. */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  return getDb().transaction((tx) => {
    const before = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!before) throw new Error(`Issue ${issueId} not found`);

    const sourceCounter = tx
      .select({ lastNumber: issueNumberCounters.lastNumber })
      .from(issueNumberCounters)
      .where(eq(issueNumberCounters.projectId, before.projectId))
      .get();
    tx.insert(issueNumberCounters)
      .values({
        projectId: before.projectId as ProjectId,
        orgId,
        lastNumber: Math.max(sourceCounter?.lastNumber ?? 0, before.number),
      })
      .onConflictDoUpdate({
        target: issueNumberCounters.projectId,
        set: {
          orgId,
          lastNumber: Math.max(sourceCounter?.lastNumber ?? 0, before.number),
        },
      })
      .run();

    const number = reserveNextIssueNumber(tx, orgId, toProjectId);
    const row = tx
      .update(issues)
      .set({
        projectId: toProjectId,
        number,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();

    if (!row) throw new Error(`Issue ${issueId} not found`);
    return toIssue(row);
  });
}

